#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;

// Incremental two-candidate boundary; original complete three-locale proof remains immutable.
public static class ExertMultiplePresentationValidation
{
    public static string Output {get;private set;}
    public static bool Running {get;private set;}
    [Serializable] class Meta {public string folder,status,runtimeHash;}
    static readonly BindingFlags Hidden=BindingFlags.Static|BindingFlags.NonPublic;
    static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    static object Helper(string name,params object[] args)=>typeof(ExertBranchPresentationValidation).GetMethod(name,Hidden).Invoke(null,args);
    static IEnumerator Frame()=>(IEnumerator)Helper("Frame");
    static void Click(Button button)=>Helper("Click",button);
    static string Hash(string path){using var h=System.Security.Cryptography.SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/running");Running=true;Output=".tools/exert-branches-1006/multiple/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(".tools/exert-branches-1006/multiple/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/ExertMultiplePresentationValidation.cs","Assets/Scripts/Editor/ExertBranchPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.CardSelection.cs","Assets/Scripts/UI/ForgeBattlefieldController.Arena.cs"}.Select(p=>p+"\t"+Hash(p))));var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("ExertMultipleValidation").AddComponent<ForgeBattlefieldController>();ui.StartCoroutine(Guard(ui));}
    static IEnumerator Guard(ForgeBattlefieldController ui){var stack=new Stack<IEnumerator>();stack.Push(Validate(ui));try{while(stack.Count>0){object current;try{var e=stack.Peek();if(!e.MoveNext()){(e as IDisposable)?.Dispose();stack.Pop();continue;}current=e.Current;if(current is IEnumerator child){stack.Push(child);continue;}}catch(Exception error){File.WriteAllText(Output+"/result.txt","FAIL "+error);throw;}yield return current;}File.WriteAllText(Output+"/result.txt","PASS: actual two-attacker native zero/one/two selections displayed separately with exact IDs, min=0/max=2/optional confirmation, deselection and confirmation ray indices; both native post-EOT pending badges and exact-ID next-untap removal; native stackablePermanent=false respected, equal projected keys do not override eligibility in zh-CN. Three-language shared contract remains in complete Exert suite. No extra first UI suite or live-network evidence.");}finally{while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();Running=false;}}
    static ForgeSeatView Read(Meta meta,string label){string p=meta.folder+"/"+label+".json";File.Copy(p,Output+"/inputs/"+label+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",label+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static IEnumerator Validate(ForgeBattlefieldController ui){bool enabled=ui.enabled;ui.enabled=false;string locale=GamePreferences.Language;var module=UnityEngine.EventSystems.EventSystem.current.currentInputModule;bool input=module!=null&&module.enabled;if(module!=null)module.enabled=false;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var noticeFlags=notices.Select(n=>n.enabled).ToArray();foreach(var n in notices)n.enabled=false;
        try{var meta=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/exert-branches-1006/native/attack-two-result.json"));Check(meta.status=="PASS"&&meta.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Native stale");File.Copy(".tools/exert-branches-1006/native/attack-two-result.json",Output+"/inputs/meta.json");GamePreferences.SetLanguage("zh-CN");float until=Time.realtimeSinceStartup+20;while(!GamePreferences.Ready&&Time.realtimeSinceStartup<until)yield return null;
            foreach(int count in new[]{0,1,2}){var v=Read(meta,"exert-choice-"+count);int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return new WaitForSecondsRealtime(.5f);yield return Frame();Helper("Clean");var panel=GameObject.Find("CardSelection");Check(v.request.minCount==0&&v.request.maxCount==2&&v.request.selectedCount==count,"Native multi gate");var candidates=v.request.options.Where(o=>o.card?.name=="Glory-Bound Initiate").ToArray();Check(candidates.Length==2&&candidates.Select(o=>o.card.id).Distinct().Count()==2,"Distinct identities absent");Check(candidates.All(o=>panel.GetComponentsInChildren<Transform>().Any(t=>t.name=="ChoiceCard_"+o.card.id)),"Candidates collapse");Check(!panel.GetComponentsInChildren<Transform>().Any(t=>t.name=="Order"),"Exert shows ordering");int confirm=ui.OptionIndex("confirm-cards");Check(confirm>=0,"Optional multi confirm absent");var choice=candidates.Last();var artwork=panel.GetComponentsInChildren<Button>().Single(b=>b.name=="Artwork"&&b.transform.parent.name=="ChoiceCard_"+choice.card.id);Click(artwork);Check(calls==1&&last==ui.OptionIndex(choice.id),"Multi ID/deselect ray mismatch");ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();panel=GameObject.Find("CardSelection");Click(panel.GetComponentsInChildren<Button>().Single(b=>b.name=="SelectionAction_"+confirm));Check(calls==2&&last==confirm,"Multi confirm mismatch");if(count==2){ScreenCapture.CaptureScreenshot(Output+"/two-selected.png");yield return Frame();}}
            foreach(string label in new[]{"pending-after-eot","next-untap"}){var v=Read(meta,label);ui.Present(v,1,false,null,null,"");yield return Frame();Helper("Clean");var pair=v.players[0].battlefield.Where(c=>!c.land).ToArray();bool pending=label=="pending-after-eot";int badges=UnityEngine.Object.FindObjectsByType<RectTransform>(FindObjectsSortMode.None).Count(t=>t.name=="Exerted"&&t.gameObject.activeInHierarchy);Check(badges==(pending?2:0),"Both exert badges did not follow native expiry");Check(pair.All(c=>GameObject.Find("Card_"+c.id)!=null),"Native nonstackable identities collapsed");if(pending){Check(pair.All(c=>c.stackableStateKnown&&!c.stackablePermanent),"Unexpected native group eligibility");Check(ForgeBattlefieldController.ArenaGroupKey(pair[0])==ForgeBattlefieldController.ArenaGroupKey(pair[1]),"Same projected exert flags changed group key");ScreenCapture.CaptureScreenshot(Output+"/two-pending.png");yield return Frame();}}

        }finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=input;for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=noticeFlags[i];}
    }
}
#endif
